import Foundation
import Testing
@testable import OneWireFormat

struct WSBinaryTests {
    
    @Test(arguments: [
        (
            "00002435394133393537442d443034332d343742442d414241352d3245423739453036423642440000039f5c71a37200000020667479706d703432000000006d7034326d70343169736f6d69736f32",
            "59A3957D-D043-47BD-ABA5-2EB79E06B6BD",
            "0000039f5c71a372",
            1773996834674
        ),
        (
            "00002436374445314342422d363142432d343445382d423437362d3138464642423844394446340000039f5c7724790002a6f6419a14786021bb7f7aa7afeefe5ae3528e31ab66a8",
            "67DE1CBB-61BC-44E8-B476-18FFBB8D9DF4",
            "0000039f5c772479",
            1773997195385
        ),
        (
            "00002442383032433636422d324638322d343643312d393733432d3332393939384135463646320000039f5c74264b000197c7419a062460213b7f6797a9b80f33e218dc5b894c12",
            "B802C66B-2F82-46C1-973C-329998A5F6F2",
            "0000039f5c74264b",
            1773996999243
        ),
        (
            "002441373741304641332d313342462d343832332d413934422d3435413333343436363943340000039f5c92331600000020667479706d703432000000006d7034326d70343169736f6d",
            "A77A0FA3-13BF-4823-A94B-45A3344669C4",
            "0000039f5c923316",
            1773998968598
        ),
        (
            "002434394634343938332d324532452d343444372d384134322d3634374243434139344545340000039f5c9232a1000000e46d6f6f66000000106d6668640000000000000001",
            "49F44983-2E2E-44D7-8A42-647BCCA94EE4",
            "0000039f5c9232a1",
            1773998968481
        ),
        (
            "",
            "A8E7E10D-C549-456A-8B1D-CDBF72398B07",
            "0000039fb5bb7656",
            1775494845014
        ),
        (
            "",
            "65D369F1-00C3-4221-85DA-E87193B36CBF",
            "0000039fb5bb7653",
            1775494845011
        )
    ])
    func parse_realPackets(
        hex: String,
        expectedId: String,
        expectedTsHex: String,
        expectedTsMillis: Int64
    ) throws {
        
        guard let data = Data(hex: hex) else {
            Issue.record("Invalid hex")
            return
        }
        
        let frame = try WSBinary.parse(data: data)
        
        // --- ID ---
        #expect(frame.streamId.uuidString == expectedId)
        
        // --- TIMESTAMP (millis) ---
        let actualMillis = Int64(frame.ts.timeIntervalSince1970 * 1000.0)
        #expect(actualMillis == expectedTsMillis)
        
        // --- TIMESTAMP BYTES ---
        let tsOffset = data.count - frame.payload.count - 8
        let tsBytes = Data(data[tsOffset..<(tsOffset + 8)])
        
        #expect(tsBytes.hexString() == expectedTsHex)
        
        // --- sanity ---
        #expect(tsBytes[0] == 0x00)
        #expect(tsBytes[1] == 0x00)
        
        // --- PAYLOAD (не жёстко) ---
        Helper.printKnownPayloadByPrefix(frame.payload)
    }
}
